sys_script_include.script:
var ClaudeConnector = Class.create();
ClaudeConnector.prototype = {
    initialize: function() {
        this.baseUrl     = gs.getProperty('x_146833_claudec_0.base_url',  'https://api.servicesessentials.ibm.com');
        this.authToken   = gs.getProperty('x_146833_claudec_0.auth_token', '');
        this.model       = gs.getProperty('x_146833_claudec_0.model',      'claude-sonnet-5');
        this.maxTokens   = parseInt(gs.getProperty('x_146833_claudec_0.max_tokens', '4096'), 10);
        this.messagesUrl = this.baseUrl.replace(/\/$/, '') + '/v1/messages';
    },

    // ─── Tool schemas ─────────────────────────────────────────────────────────
    TOOL_SCHEMAS: [
        {
            name: 'get_current_datetime',
            description: 'Returns the current server date and time formatted with the given strftime-style format string.',
            input_schema: {
                type: 'object',
                properties: {
                    date_format: {
                        type: 'string',
                        description: 'strftime format string, e.g. "%Y-%m-%d %H:%M:%S". Defaults to "%Y-%m-%d %H:%M:%S".'
                    }
                },
                required: []
            }
        },
        {
            name: 'add_duration_to_datetime',
            description: 'Adds a duration to a datetime string and returns the resulting datetime.',
            input_schema: {
                type: 'object',
                properties: {
                    datetime_str: {
                        type: 'string',
                        description: 'The input datetime string, e.g. "2025-01-15".'
                    },
                    duration: {
                        type: 'number',
                        description: 'Amount to add (integer). Defaults to 0.'
                    },
                    unit: {
                        type: 'string',
                        enum: ['seconds','minutes','hours','days','weeks','months','years'],
                        description: 'Time unit. Defaults to "days".'
                    },
                    input_format: {
                        type: 'string',
                        description: 'strftime format of datetime_str. Defaults to "%Y-%m-%d".'
                    }
                },
                required: ['datetime_str']
            }
        },
        {
            name: 'set_reminder',
            description: 'Simulates setting a timed reminder. Returns a confirmation string.',
            input_schema: {
                type: 'object',
                properties: {
                    content: {
                        type: 'string',
                        description: 'The reminder message content.'
                    },
                    timestamp: {
                        type: 'string',
                        description: 'When the reminder should fire, e.g. "2025-06-01 09:00:00".'
                    }
                },
                required: ['content', 'timestamp']
            }
        },
        {
            name: 'batch_tool',
            description: 'Invokes multiple other tools simultaneously in one call. Results are returned in the same order.',
            input_schema: {
                type: 'object',
                properties: {
                    invocations: {
                        type: 'array',
                        description: 'Array of tool invocations to run.',
                        items: {
                            type: 'object',
                            properties: {
                                name:      { type: 'string', description: 'Name of the tool to invoke.' },
                                arguments: { type: 'string', description: 'JSON-encoded string of the input arguments for the tool.' }
                            },
                            required: ['name', 'arguments']
                        }
                    }
                },
                required: ['invocations']
            }
        }
    ],

    // ─── Tool dispatch ────────────────────────────────────────────────────────
    /**
     * Execute a single tool call by name.
     * @param {string} name  - Tool name
     * @param {Object} input - Tool input object
     * @returns {string}     - Tool result as a string
     */
    dispatch_tool: function(name, input) {
        if (name === 'get_current_datetime') {
            return this._tool_get_current_datetime(input);
        } else if (name === 'add_duration_to_datetime') {
            return this._tool_add_duration_to_datetime(input);
        } else if (name === 'set_reminder') {
            return this._tool_set_reminder(input);
        } else if (name === 'batch_tool') {
            return this._tool_batch(input);
        }
        return 'Error: unknown tool "' + name + '"';
    },

    _pad2: function(n) {
        return (n < 10 ? '0' : '') + n;
    },

    _tool_get_current_datetime: function(input) {
        var fmt = (input && input.date_format) ? input.date_format : '%Y-%m-%d %H:%M:%S';
        if (!fmt) { return 'Error: date_format cannot be empty'; }
        var gdt = new GlideDateTime();
        var result = fmt
            .replace(/%Y/g, gdt.getYearLocalTime())
            .replace(/%m/g, this._pad2(gdt.getMonthLocalTime()))
            .replace(/%d/g, this._pad2(gdt.getDayOfMonthLocalTime()))
            .replace(/%H/g, this._pad2(gdt.getHourLocalTime()))
            .replace(/%M/g, this._pad2(gdt.getMinutesLocalTime()))
            .replace(/%S/g, this._pad2(gdt.getSecondsLocalTime()));
        return result;
    },

    _tool_add_duration_to_datetime: function(input) {
        var datetimeStr = (input && input.datetime_str)  ? input.datetime_str  : '';
        var duration    = (input && input.duration != null) ? parseInt(input.duration, 10) : 0;
        var unit        = (input && input.unit)          ? input.unit          : 'days';

        if (!datetimeStr) { return 'Error: datetime_str is required'; }

        var gdt = new GlideDateTime();
        gdt.setDisplayValueInternal(datetimeStr);

        if (unit === 'months') {
            var y  = gdt.getYearLocalTime();
            var mo = gdt.getMonthLocalTime() + duration;
            y  = y + Math.floor((mo - 1) / 12);
            mo = ((mo - 1) % 12 + 12) % 12 + 1;
            var daysInMonth = [0,31,28,31,30,31,30,31,31,30,31,30,31];
            if (mo === 2) {
                daysInMonth[2] = (y % 4 === 0 && (y % 100 !== 0 || y % 400 === 0)) ? 29 : 28;
            }
            var day = Math.min(gdt.getDayOfMonthLocalTime(), daysInMonth[mo]);
            var newGdt = new GlideDateTime();
            newGdt.setDisplayValueInternal(y + '-' + this._pad2(mo) + '-' + this._pad2(day) +
                ' ' + this._pad2(gdt.getHourLocalTime()) + ':' + this._pad2(gdt.getMinutesLocalTime()) + ':' + this._pad2(gdt.getSecondsLocalTime()));
            return newGdt.getDisplayValueInternal();
        } else if (unit === 'years') {
            var newY = gdt.getYearLocalTime() + duration;
            var newGdtY = new GlideDateTime();
            newGdtY.setDisplayValueInternal(newY + '-' + this._pad2(gdt.getMonthLocalTime()) + '-' + this._pad2(gdt.getDayOfMonthLocalTime()) +
                ' ' + this._pad2(gdt.getHourLocalTime()) + ':' + this._pad2(gdt.getMinutesLocalTime()) + ':' + this._pad2(gdt.getSecondsLocalTime()));
            return newGdtY.getDisplayValueInternal();
        }

        var ms = 0;
        if      (unit === 'seconds') { ms = duration * 1000; }
        else if (unit === 'minutes') { ms = duration * 60000; }
        else if (unit === 'hours')   { ms = duration * 3600000; }
        else if (unit === 'days')    { ms = duration * 86400000; }
        else if (unit === 'weeks')   { ms = duration * 604800000; }
        else { return 'Error: unsupported unit "' + unit + '"'; }

        gdt.add(ms);
        return gdt.getDisplayValueInternal();
    },

    _tool_set_reminder: function(input) {
        var content   = (input && input.content)   ? input.content   : '';
        var timestamp = (input && input.timestamp) ? input.timestamp : '';
        if (!content || !timestamp) { return 'Error: content and timestamp are required'; }
        return 'Reminder set for ' + timestamp + ': ' + content;
    },

    _tool_batch: function(input) {
        var invocations = (input && input.invocations) ? input.invocations : [];
        var results = [];
        for (var i = 0; i < invocations.length; i++) {
            var inv  = invocations[i];
            var name = inv.name || '';
            var args = {};
            try { args = JSON.parse(inv.arguments || '{}'); } catch(e) {}
            var result = this.dispatch_tool(name, args);
            results.push({ tool: name, result: result });
        }
        return JSON.stringify(results);
    },

    // ─── Agentic chat (tool-use loop) ─────────────────────────────────────────
    /**
     * Send a chat request to Claude with agentic tool-use support.
     * Delegates to ClaudeConversationManager.run_conversation() which persists
     * every content block (user text, assistant text, tool_use, tool_result) to
     * x_146833_claudec_0_message and maintains the x_146833_claudec_0_session record.
     * Also writes a summary audit row via ClaudeRequestLogger.
     *
     * @param {Array}  messages - Array of {role, content} objects
     * @param {Object} opts     - Optional: model, system_prompt, stop_sequences, max_tokens,
     *                            session_id, prompt, temperature (for logging)
     * @returns {Object}        - {success, text, inputTokens, outputTokens, model, toolRounds, error}
     */
    chatWithTools: function(messages, opts) {
        opts = opts || {};
        var systemPrompt = opts.system_prompt || '';
        var model        = opts.model         || this.model;
        var maxTok       = opts.max_tokens    || this.maxTokens;
        var temperature  = (opts.temperature != null) ? opts.temperature : 1.0;
        var sessionId    = opts.session_id    || 'default';

        // Write pending audit row
        var logger    = new x_146833_claudec_0.ClaudeRequestLogger();
        var startMs   = new GlideDateTime().getNumericValue();
        var stagingId = logger.createPending({
            session_id:    sessionId,
            model:         model,
            prompt:        opts.prompt || '',
            system_prompt: systemPrompt,
            max_tokens:    maxTok
        });

        // Delegate to ClaudeConversationManager for the full loop + persistence
        var mgr    = new x_146833_claudec_0.ClaudeConversationManager();
        var result = mgr.run_conversation(messages, {
            session_id:  sessionId,
            system:      systemPrompt,
            temperature: temperature,
            model:       model,
            max_tokens:  maxTok
        });

        var durationMs = new GlideDateTime().getNumericValue() - startMs;

        if (!result.success) {
            logger.markError(stagingId, result.error, durationMs);
            return { success: false, error: result.error };
        }

        logger.markSuccess(stagingId, {
            text:         result.text,
            model:        result.model,
            inputTokens:  result.inputTokens,
            outputTokens: result.outputTokens,
            toolRounds:   result.toolRounds,
            durationMs:   durationMs
        });

        return {
            success:      true,
            text:         result.text,
            inputTokens:  result.inputTokens,
            outputTokens: result.outputTokens,
            model:        result.model,
            toolRounds:   result.toolRounds
        };
    },

    /**
     * Send a chat request to the Claude API (no tools, plain text).
     * @param {Array}  messages - Array of {role, content} objects
     * @param {Object} opts     - Optional: model, system_prompt, prefill, stop_sequences
     * @returns {Object}        - {success, text, inputTokens, outputTokens, model, error}
     */
    chat: function(messages, opts) {
        opts = opts || {};

        var model        = opts.model         || this.model;
        var systemPrompt = opts.system_prompt  || '';
        var prefill      = opts.prefill        || '';
        var stopSeqs     = opts.stop_sequences || [];
        var temperature  = (opts.temperature != null) ? opts.temperature : 1.0;

        var msgsCopy = [];
        for (var i = 0; i < messages.length; i++) {
            msgsCopy.push({ role: messages[i].role, content: messages[i].content });
        }
        if (prefill && msgsCopy.length > 0 && msgsCopy[msgsCopy.length - 1].role === 'user') {
            msgsCopy[msgsCopy.length - 1].content += '\n\nRespond starting with: ' + prefill;
        }

        var payload = {
            model:       model,
            max_tokens:  this.maxTokens,
            messages:    msgsCopy,
            temperature: temperature
        };
        if (systemPrompt) { payload.system = systemPrompt; }
        if (stopSeqs && stopSeqs.length > 0) { payload.stop_sequences = stopSeqs; }

        var request = new sn_ws.RESTMessageV2();
        request.setEndpoint(this.messagesUrl);
        request.setHttpMethod('POST');
        request.setRequestHeader('x-api-key',         this.authToken);
        request.setRequestHeader('anthropic-version', '2023-06-01');
        request.setRequestHeader('content-type',      'application/json');
        request.setRequestBody(JSON.stringify(payload));
        request.setHttpTimeout(120000);

        try {
            var response   = request.execute();
            var statusCode = response.getStatusCode();
            var body       = response.getBody();

            if (statusCode < 200 || statusCode >= 300) {
                return { success: false, error: 'API error ' + statusCode + ': ' + body };
            }

            var json = JSON.parse(body);
            var text = '';
            if (json.content && json.content.length > 0) {
                for (var c = 0; c < json.content.length; c++) {
                    if (json.content[c].type === 'text') {
                        text += json.content[c].text;
                    }
                }
            }
            var usage       = json.usage || {};
            var inputTokens = usage.input_tokens  || 0;
            var outTokens   = usage.output_tokens || 0;
            var modelUsed   = json.model || model;

            return {
                success:      true,
                text:         text,
                inputTokens:  inputTokens,
                outputTokens: outTokens,
                model:        modelUsed
            };
        } catch (e) {
            return { success: false, error: e.toString() };
        }
    },

    type: 'ClaudeConnector'
};
